<?php
namespace Azula\SmsStudio;

final class M6Activity
{
    public function __construct(private M6Store $s,private ?AudienceSource $source=null){}
    public static function label(string $event):string
    {
        return ['bulk_completed'=>'Execution processing completed (acceptance is not delivery)','bulk_worker_observed'=>'Execution worker context observed','draft_created'=>'Campaign created','audience_started'=>'Audience preparation started','audience_complete'=>'Audience prepared','message_edited'=>'Message edited','review_saved'=>'Review saved','schedule_planned'=>'Schedule created or changed','final_capture_complete'=>'Final audience validated','sending_approval_granted'=>'Sending approval granted','sending_approval_invalidated'=>'Sending approval invalidated','submission_explicitly_authorized'=>'Submission explicitly authorized','submission_started'=>'Submission started','provider_accepted'=>'Provider accepted request','provider_rejected'=>'Provider rejected request','submission_unknown'=>'Unknown provider outcome — do not resend','campaign_canceled'=>'Campaign cancelled','campaign_trashed'=>'Campaign moved to Trash','campaign_restored'=>'Campaign restored without approval','recipient_withheld_suppression'=>'Recipient withheld by SMS suppression'][$event]??ucfirst(str_replace('_',' ',$event));
    }
    public function read(int $id,int $after=0):array
    {
        $base=(new M5Activity($this->s->database,$this->s->crypto))->rows($id,$after);foreach($base['events'] as &$e)$e['label']=self::label($e['event']);unset($e);
        foreach($base['attempts'] as &$attempt){if(M7Settings::modern()){$row=$this->s->row('SELECT receipt FROM '.$this->s->table('attempts').' WHERE id=%d AND campaign_id=%d',$attempt['id'],$id);try{$receipt=$this->s->crypto->open($row['receipt']);$attempt['submitted_message']=$receipt['submitted_message']??null;}catch(\Throwable $e){$attempt['submitted_message']=null;}}$attempt['reason']=['1901'=>'Accepted by provider; delivery unverified','1902'=>'Invalid request','1903'=>'Invalid provider credentials','1904'=>'Invalid sender','1905'=>'Invalid destination','1906'=>'Insufficient provider credit','1907'=>'Provider server updating','1908'=>'Invalid delay format','1909'=>'Invalid message','1910'=>'Invalid language','1911'=>'Message too long','1912'=>'Invalid environment'][$attempt['code']??'']??($attempt['state']==='unknown'?'Unknown outcome; do not resend':'See recorded request outcome');}unset($attempt);
        $c=$this->s->row('SELECT * FROM '.$this->s->table('campaigns').' WHERE id=%d',$id);if(!$c)throw new ControlledTestException('Campaign not found.');$a=$c['audience_id']?$this->s->campaigns->m2->store()->audience((int)$c['audience_id']):null;$message=$this->s->campaigns->m2->message($c);$schedule=$this->s->campaigns->get($id);if(M7Settings::modern()&&$a&&(int)json_decode($a['counts_json'],true)['prepared']===1){foreach($base['attempts'] as $attempt)if(!empty($attempt['submitted_message'])){$message=$attempt['submitted_message'];break;}}$out=['claimed_recipients'=>0,'requests'=>0,'accepted'=>0,'rejected'=>0,'unknown'=>0,'aborted_not_sent'=>0,'points'=>'0','cost_missing'=>0,'last_activity'=>0];
        $totals=$this->s->rows('SELECT state,COUNT(*) requests,SUM(recipient_count) recipients,MAX(claimed_at) last_activity FROM '.$this->s->table('attempts').' WHERE campaign_id=%d GROUP BY state',$id);foreach($totals as $r){$out['requests']+=(int)$r['requests'];$out['claimed_recipients']+=(int)$r['recipients'];$key=['accepted'=>'accepted','rejected'=>'rejected','unknown'=>'unknown','aborted'=>'aborted_not_sent'][$r['state']]??null;if($key)$out[$key]+=(int)$r['recipients'];$out['last_activity']=max($out['last_activity'],(int)$r['last_activity']);}
        $costs=$this->s->rows('SELECT id,cost FROM '.$this->s->table('attempts').' WHERE campaign_id=%d ORDER BY id ASC LIMIT 10001',$id);if(count($costs)>10000)$out['points']=null;else foreach($costs as $row){if($row['cost']===null)$out['cost_missing']++;else $out['points']=ExactPoints::add($out['points'],(string)$row['cost']);}
        $base['overview']=['id'=>$id,'name'=>$c['name'],'segment_id'=>(int)$c['segment_id'],'created'=>(int)$c['created_at'],'scheduled'=>$schedule&&!in_array($schedule['state'],['canceled','missed'],true)?CairoTime::label((int)$schedule['start_at']):null,'state'=>$c['state'],'recipients'=>$a?(int)json_decode($a['counts_json'],true)['prepared']:0,'message'=>$message,'metrics'=>MessageMetrics::calculate($message,$a?(int)json_decode($a['counts_json'],true)['prepared']:0,M2Repository::rate())];if(RC1Status::modern()){$execution=RC1Status::campaign($this->s,$id);if($execution){$base['overview']['state']=$execution['label'];$base['overview']['scheduled']=$execution['scheduled']?CairoTime::label($execution['start']):null;}}$base['results']=$out;$base['sending']=(new M6SendService($this->s,$this->source))->status($id);return $base;
    }
}
